import numpy as np

def select_next_node(current_node: int, depot: int, unvisited_nodes: np.ndarray, rest_capacity: np.ndarray, demands: np.ndarray, distance_matrix: np.ndarray) -> int:
    """Select next node using a two-step lookahead heuristic."""
    best_node = -1
    best_total = float('inf')
    best_demand = -1

    for node in unvisited_nodes:
        demand = demands[node]
        if demand > rest_capacity:
            continue
        dist_to_node = distance_matrix[current_node][node]
        # Remaining capacity after visiting node
        remaining = rest_capacity - demand
        # Find best next node from this node (simple nearest feasible)
        next_dist = 0.0
        if remaining > 0:
            best_next = -1
            best_next_dist = float('inf')
            for nxt in unvisited_nodes:
                if nxt == node:
                    continue
                if demands[nxt] <= remaining:
                    d = distance_matrix[node][nxt]
                    if d < best_next_dist:
                        best_next_dist = d
                        best_next = nxt
            if best_next != -1:
                next_dist = best_next_dist
        total = dist_to_node + next_dist
        # Prefer higher demand on tie
        if total < best_total or (total == best_total and demand > best_demand):
            best_total = total
            best_node = node
            best_demand = demand

    if best_node == -1:
        # Fallback to original heuristic if no feasible node found (shouldn't happen)
        best_score = -1
        for node in unvisited_nodes:
            demand = demands[node]
            distance = distance_matrix[current_node][node]
            if demand <= rest_capacity:
                score = demand / distance if distance > 0 else float('inf')
                if score > best_score:
                    best_score = score
                    best_node = node
    return best_node
